const page = await browser.goto('https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000320193&type=8-K&dateb=&owner=include&count=40');
const text = await browser.js('document.body.innerText');
return text.slice(0, 3000);

const page = await browser.goto('https://www.sec.gov/Archives/edgar/data/320193/000032019326000005/');
const text = await browser.js('document.body.innerText');
return text.slice(0, 3000);

const page = await browser.goto('https://www.sec.gov/Archives/edgar/data/320193/000032019326000005/0000320193-26-000005-index.html');
const text = await browser.js('document.body.innerText');
return text.slice(0, 3000);

const page = await browser.goto('https://www.sec.gov/Archives/edgar/data/320193/000032019326000005/');
const links = await browser.js(`
  Array.from(document.querySelectorAll('a')).map(a => ({href: a.href, text: a.textContent.trim()}))
`);
return links;

const page = await browser.goto('https://www.sec.gov/Archives/edgar/data/320193/000032019326000005/');
// find the backend node id for the link to aapl-20260129.htm
const result = await browser.js(`
  (function(){
    const a = Array.from(document.querySelectorAll('a')).find(a => a.getAttribute('href') === 'aapl-20260129.htm');
    return a ? a.outerHTML : null;
  })()
`);
return result;

const fs = await import('node:fs/promises');
const url = 'https://www.sec.gov/Archives/edgar/data/320193/000032019326000005/aapl-20260129.htm';
const html = await browser.js(`
  fetch(${JSON.stringify(url)}).then(r => r.text())
`);
await fs.writeFile('aapl-20260129.htm', html, 'utf-8');
return {length: html.length, snippet: html.slice(0,500)};

const page = await browser.goto('https://www.sec.gov/Archives/edgar/data/320193/000032019326000005/aapl-20260129.htm');
const title = await browser.js('document.title');
const bodyText = await browser.js('document.body.innerText.slice(0,1000)');
return {title, bodyText, url: page.url};
